        private static Dictionary<string, string> Map()
        {
            if (map != null)
            {
                return map;
            }

            map = new Dictionary<string, string>(801, StringComparer.Ordinal);
            for (int i = 0; i < Pairs.GetLength(0); i++)
            {
                map[Pairs[i, 0]] = Pairs[i, 1];
            }

            return map;
        }

        /// <summary>词条的中文名；查不到返回 null。</summary>
        public static string Name(string tag)
        {
            if (string.IsNullOrEmpty(tag))
            {
                return null;
            }

            string value;
            return Map().TryGetValue(tag, out value) ? value : null;
        }

        public static int Count
        {
            get { return Pairs.GetLength(0); }
        }
    }
